import React, { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const AdminDashboard = () => {
  const { user, token, logout } = useAuth();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('overview');
  const [stylists, setStylists] = useState([]);
  const [services, setServices] = useState([]);
  const [appointments, setAppointments] = useState([]);
  const [showStylistModal, setShowStylistModal] = useState(false);
  const [showServiceModal, setShowServiceModal] = useState(false);
  const [editingService, setEditingService] = useState(null);
  const [stylistForm, setStylistForm] = useState({ name: '', email: '', password: '', phone: '' });
  const [serviceForm, setServiceForm] = useState({ name: '', category: 'barberia', description: '', duration: 30, price: 0, stylists: [] });
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const headers = { Authorization: `Bearer ${token}` };

  const fetchData = useCallback(async () => {
    try {
      const [styRes, srvRes, aptRes] = await Promise.all([
        axios.get('/api/auth/stylists'),
        axios.get('/api/services'),
        axios.get('/api/appointments', { headers })
      ]);
      setStylists(styRes.data);
      setServices(srvRes.data);
      setAppointments(aptRes.data);
    } catch (err) { console.error(err); }
  }, [token]);

  useEffect(() => {
    if (!user || user.role !== 'admin') { navigate('/login'); return; }
    fetchData();
  }, [user, navigate, fetchData]);

  const showSuccess = (msg) => {
    setSuccessMsg(msg);
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const handleAddStylist = async (e) => {
    e.preventDefault();
    setError('');
    try {
      await axios.post('/api/auth/register-stylist', stylistForm, { headers });
      setShowStylistModal(false);
      setStylistForm({ name: '', email: '', password: '', phone: '' });
      fetchData();
      showSuccess('Estilista registrado exitosamente');
    } catch (err) {
      setError(err.response?.data?.message || 'Error al registrar estilista');
    }
  };

  const handleDeleteStylist = async (id) => {
    if (!window.confirm('¿Está seguro de eliminar este estilista?')) return;
    try {
      await axios.delete(`/api/auth/stylists/${id}`, { headers });
      fetchData();
      showSuccess('Estilista eliminado');
    } catch (err) { alert('Error al eliminar'); }
  };

  const handleSaveService = async (e) => {
    e.preventDefault();
    setError('');
    try {
      if (editingService) {
        await axios.put(`/api/services/${editingService._id}`, serviceForm, { headers });
        showSuccess('Servicio actualizado');
      } else {
        await axios.post('/api/services', serviceForm, { headers });
        showSuccess('Servicio creado');
      }
      setShowServiceModal(false);
      setEditingService(null);
      setServiceForm({ name: '', category: 'barberia', description: '', duration: 30, price: 0, stylists: [] });
      fetchData();
    } catch (err) {
      setError(err.response?.data?.message || 'Error al guardar servicio');
    }
  };

  const handleDeleteService = async (id) => {
    if (!window.confirm('¿Eliminar este servicio?')) return;
    try {
      await axios.delete(`/api/services/${id}`, { headers });
      fetchData();
      showSuccess('Servicio eliminado');
    } catch (err) { alert('Error al eliminar'); }
  };

  const openEditService = (service) => {
    setEditingService(service);
    setServiceForm({
      name: service.name,
      category: service.category,
      description: service.description || '',
      duration: service.duration,
      price: service.price,
      stylists: service.stylists?.map(s => s._id || s) || []
    });
    setShowServiceModal(true);
    setError('');
  };

  const handleLogout = () => { logout(); navigate('/login'); };

  const todayStr = new Date().toISOString().split('T')[0];
  const todayAppointments = appointments.filter(a => a.date?.slice(0, 10) === todayStr);
  const pendingCount = appointments.filter(a => a.status === 'pending').length;
  const completedToday = todayAppointments.filter(a => a.status === 'completed');
  const todayEarnings = completedToday.reduce((s, a) => s + (a.price || 0), 0);

  if (!user) return <div className="loading-screen"><div className="spinner"></div></div>;

  return (
    <div className="dashboard">
      {/* Sidebar */}
      <aside className="sidebar">
        <div className="sidebar-brand"><span>💈</span> BarberShop</div>
        <nav className="sidebar-nav">
          {[
            { id: 'overview', icon: '📊', label: 'Panel General' },
            { id: 'stylists', icon: '👤', label: 'Estilistas' },
            { id: 'services', icon: '✂️', label: 'Servicios' },
            { id: 'appointments', icon: '📅', label: 'Citas' }
          ].map(tab => (
            <button key={tab.id} className={`sidebar-link ${activeTab === tab.id ? 'active' : ''}`} onClick={() => setActiveTab(tab.id)}>
              <span className="icon">{tab.icon}</span> {tab.label}
            </button>
          ))}
        </nav>
        <div className="sidebar-user">
          <div className="sidebar-user-info">
            <div className="avatar">{user.name?.[0]}</div>
            <div><div className="name">{user.name}</div><div className="role">Administrador</div></div>
          </div>
          <button className="sidebar-link" onClick={handleLogout}><span className="icon">🚪</span> Cerrar Sesión</button>
        </div>
      </aside>

      {/* Mobile Nav */}
      <div className="mobile-nav">
        {[
          { id: 'overview', icon: '📊', label: 'Panel' },
          { id: 'stylists', icon: '👤', label: 'Estilistas' },
          { id: 'services', icon: '✂️', label: 'Servicios' },
          { id: 'appointments', icon: '📅', label: 'Citas' }
        ].map(tab => (
          <button key={tab.id} className={activeTab === tab.id ? 'active' : ''} onClick={() => setActiveTab(tab.id)}>
            <span className="icon">{tab.icon}</span> {tab.label}
          </button>
        ))}
      </div>

      {/* Main Content */}
      <main className="dashboard-main">
        {successMsg && (
          <div style={{ background: 'rgba(46,204,113,0.1)', border: '1px solid var(--success)', padding: '12px 20px', borderRadius: 'var(--radius-sm)', marginBottom: '20px', color: 'var(--success)' }}>
            ✅ {successMsg}
          </div>
        )}

        {/* OVERVIEW TAB */}
        {activeTab === 'overview' && (
          <div>
            <h2 style={{ marginBottom: '24px' }}>Panel General</h2>
            <div className="stats-grid">
              <div className="stat-card gold"><div className="stat-icon">💰</div><div className="stat-value">S/ {todayEarnings}</div><div className="stat-label">Ingresos Hoy</div></div>
              <div className="stat-card info"><div className="stat-icon">📅</div><div className="stat-value">{todayAppointments.length}</div><div className="stat-label">Citas Hoy</div></div>
              <div className="stat-card warning"><div className="stat-icon">⏳</div><div className="stat-value">{pendingCount}</div><div className="stat-label">Pendientes</div></div>
              <div className="stat-card success"><div className="stat-icon">👤</div><div className="stat-value">{stylists.length}</div><div className="stat-label">Estilistas</div></div>
            </div>
            <h3 style={{ marginBottom: '16px' }}>Citas de Hoy</h3>
            {todayAppointments.length === 0 ? (
              <p style={{ color: 'var(--text-muted)' }}>No hay citas programadas para hoy</p>
            ) : (
              <table className="data-table">
                <thead><tr><th>Cliente</th><th>Servicio</th><th>Hora</th><th>Estilista</th><th>Estado</th></tr></thead>
                <tbody>
                  {todayAppointments.map(a => (
                    <tr key={a._id}>
                      <td>{a.clientName}</td>
                      <td>{a.service?.name}</td>
                      <td>{a.startTime} - {a.endTime}</td>
                      <td>{a.stylist?.name}</td>
                      <td><span className={`badge badge-${a.status}`}>{a.status}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}

        {/* STYLISTS TAB */}
        {activeTab === 'stylists' && (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
              <h2>Gestión de Estilistas</h2>
              <button className="btn btn-gold btn-sm" onClick={() => { setShowStylistModal(true); setError(''); }}>+ Nuevo Estilista</button>
            </div>
            <table className="data-table">
              <thead><tr><th>Nombre</th><th>Email</th><th>Teléfono</th><th>Acciones</th></tr></thead>
              <tbody>
                {stylists.map(s => (
                  <tr key={s._id}>
                    <td style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                      <div className="avatar" style={{ width: 32, height: 32, fontSize: '0.8rem' }}>{s.name?.[0]}</div> {s.name}
                    </td>
                    <td>{s.email}</td>
                    <td>{s.phone || '—'}</td>
                    <td><button className="btn btn-danger btn-sm" onClick={() => handleDeleteStylist(s._id)}>Eliminar</button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* SERVICES TAB */}
        {activeTab === 'services' && (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
              <h2>Gestión de Servicios</h2>
              <button className="btn btn-gold btn-sm" onClick={() => { setEditingService(null); setServiceForm({ name: '', category: 'barberia', description: '', duration: 30, price: 0, stylists: [] }); setShowServiceModal(true); setError(''); }}>+ Nuevo Servicio</button>
            </div>
            <table className="data-table">
              <thead><tr><th>Servicio</th><th>Categoría</th><th>Duración</th><th>Precio</th><th>Estilistas</th><th>Acciones</th></tr></thead>
              <tbody>
                {services.map(s => (
                  <tr key={s._id}>
                    <td><strong>{s.name}</strong><br /><span style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>{s.description}</span></td>
                    <td style={{ textTransform: 'capitalize' }}>{s.category}</td>
                    <td>{s.duration} min</td>
                    <td style={{ color: 'var(--gold)', fontWeight: 600 }}>S/ {s.price}</td>
                    <td>{s.stylists?.map(st => st.name || '').join(', ') || '—'}</td>
                    <td>
                      <div style={{ display: 'flex', gap: '8px' }}>
                        <button className="btn btn-info btn-sm" onClick={() => openEditService(s)}>Editar</button>
                        <button className="btn btn-danger btn-sm" onClick={() => handleDeleteService(s._id)}>Eliminar</button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* APPOINTMENTS TAB */}
        {activeTab === 'appointments' && (
          <div>
            <h2 style={{ marginBottom: '24px' }}>Todas las Citas</h2>
            {appointments.length === 0 ? (
              <p style={{ color: 'var(--text-muted)' }}>No hay citas registradas</p>
            ) : (
              <table className="data-table">
                <thead><tr><th>Cliente</th><th>Teléfono</th><th>Servicio</th><th>Fecha</th><th>Hora</th><th>Estilista</th><th>Precio</th><th>Estado</th></tr></thead>
                <tbody>
                  {appointments.map(a => (
                    <tr key={a._id}>
                      <td>{a.clientName}</td>
                      <td>{a.clientPhone}</td>
                      <td>{a.service?.name}</td>
                      <td>{new Date(a.date).toLocaleDateString()}</td>
                      <td>{a.startTime}</td>
                      <td>{a.stylist?.name}</td>
                      <td style={{ color: 'var(--gold)' }}>S/ {a.price}</td>
                      <td><span className={`badge badge-${a.status}`}>{a.status}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}
      </main>

      {/* Stylist Modal */}
      {showStylistModal && (
        <div className="modal-overlay" onClick={() => setShowStylistModal(false)}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <h2>Registrar Nuevo Estilista</h2>
            {error && <div className="error-msg">{error}</div>}
            <form onSubmit={handleAddStylist}>
              <div className="form-group" style={{ marginBottom: '16px' }}>
                <label>Nombre *</label>
                <input type="text" value={stylistForm.name} onChange={e => setStylistForm({ ...stylistForm, name: e.target.value })} required />
              </div>
              <div className="form-group" style={{ marginBottom: '16px' }}>
                <label>Email *</label>
                <input type="email" value={stylistForm.email} onChange={e => setStylistForm({ ...stylistForm, email: e.target.value })} required />
              </div>
              <div className="form-group" style={{ marginBottom: '16px' }}>
                <label>Contraseña *</label>
                <input type="password" value={stylistForm.password} onChange={e => setStylistForm({ ...stylistForm, password: e.target.value })} required minLength={6} />
              </div>
              <div className="form-group" style={{ marginBottom: '16px' }}>
                <label>Teléfono</label>
                <input type="tel" value={stylistForm.phone} onChange={e => setStylistForm({ ...stylistForm, phone: e.target.value })} />
              </div>
              <div className="modal-actions">
                <button type="button" className="btn btn-outline btn-sm" onClick={() => setShowStylistModal(false)}>Cancelar</button>
                <button type="submit" className="btn btn-gold btn-sm">Registrar</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Service Modal */}
      {showServiceModal && (
        <div className="modal-overlay" onClick={() => setShowServiceModal(false)}>
          <div className="modal" onClick={e => e.stopPropagation()}>
            <h2>{editingService ? 'Editar Servicio' : 'Nuevo Servicio'}</h2>
            {error && <div className="error-msg">{error}</div>}
            <form onSubmit={handleSaveService}>
              <div className="form-group" style={{ marginBottom: '16px' }}>
                <label>Nombre *</label>
                <input type="text" value={serviceForm.name} onChange={e => setServiceForm({ ...serviceForm, name: e.target.value })} required />
              </div>
              <div className="form-group" style={{ marginBottom: '16px' }}>
                <label>Categoría *</label>
                <select value={serviceForm.category} onChange={e => setServiceForm({ ...serviceForm, category: e.target.value })}>
                  <option value="barberia">Barbería</option>
                  <option value="manicura">Manicura</option>
                  <option value="pintado">Pintado</option>
                  <option value="lizado">Alisado</option>
                  <option value="tratamiento">Tratamiento</option>
                  <option value="otro">Otro</option>
                </select>
              </div>
              <div className="form-group" style={{ marginBottom: '16px' }}>
                <label>Descripción</label>
                <textarea value={serviceForm.description} onChange={e => setServiceForm({ ...serviceForm, description: e.target.value })} rows={2} />
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', marginBottom: '16px' }}>
                <div className="form-group">
                  <label>Duración (min) *</label>
                  <input type="number" value={serviceForm.duration} onChange={e => setServiceForm({ ...serviceForm, duration: Number(e.target.value) })} min={5} required />
                </div>
                <div className="form-group">
                  <label>Precio (S/) *</label>
                  <input type="number" value={serviceForm.price} onChange={e => setServiceForm({ ...serviceForm, price: Number(e.target.value) })} min={0} step={0.5} required />
                </div>
              </div>
              <div className="form-group" style={{ marginBottom: '16px' }}>
                <label>Estilistas Asignados</label>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', marginTop: '4px' }}>
                  {stylists.map(s => (
                    <label key={s._id} style={{ display: 'flex', alignItems: 'center', gap: '6px', cursor: 'pointer', fontSize: '0.9rem', color: 'var(--text-secondary)' }}>
                      <input type="checkbox" checked={serviceForm.stylists.includes(s._id)}
                        onChange={(e) => {
                          if (e.target.checked) setServiceForm({ ...serviceForm, stylists: [...serviceForm.stylists, s._id] });
                          else setServiceForm({ ...serviceForm, stylists: serviceForm.stylists.filter(id => id !== s._id) });
                        }} />
                      {s.name}
                    </label>
                  ))}
                </div>
              </div>
              <div className="modal-actions">
                <button type="button" className="btn btn-outline btn-sm" onClick={() => { setShowServiceModal(false); setEditingService(null); }}>Cancelar</button>
                <button type="submit" className="btn btn-gold btn-sm">{editingService ? 'Guardar Cambios' : 'Crear Servicio'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;
